mapper.select:
SELECT t.* FROM `task` t
WHERE t.`company_id` = #{companyId}
  AND (
        t.`visibility` = 'PUBLIC'
     OR EXISTS (SELECT 1 FROM `task_viewer`   tv WHERE tv.`task_id` = t.`id` AND tv.`user_id` = #{userId})
     OR EXISTS (SELECT 1 FROM `task_assignee` ta WHERE ta.`task_id` = t.`id` AND ta.`user_id` = #{userId})
  )
  AND (
        t.`completed_by` = #{userId}
     OR EXISTS (SELECT 1 FROM `task_assignee` ta2 WHERE ta2.`task_id` = t.`id` AND ta2.`user_id` = #{userId})
  )
ORDER BY t.`created_at` DESC
